using DriveOS.Modules.CurriculumPedagogy.Domain.RemediationPlans;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Persistence.Repositories;
internal sealed class RemediationPlanRepository(CurriculumPedagogyDbContext db):IRemediationPlanRepository{public Task<RemediationPlan?>GetByIdForUpdateAsync(OrganizationId org,RemediationPlanId id,CancellationToken ct=default)=>db.RemediationPlans.Include(x=>x.Targets).SingleOrDefaultAsync(x=>x.OrganizationId==org&&x.Id==id,ct);public Task<bool>HasOpenPlanAsync(OrganizationId org,TrainingPathId path,CancellationToken ct=default)=>db.RemediationPlans.AsNoTracking().AnyAsync(x=>x.OrganizationId==org&&x.TrainingPathId==path&&(x.Status==RemediationPlanStatus.Draft||x.Status==RemediationPlanStatus.Active),ct);public async Task AddAsync(RemediationPlan p,CancellationToken ct=default)=>await db.RemediationPlans.AddAsync(p,ct);}
